note("The ridge came out like a strip of butter: a pile of umber, ochre, smalt and a little lead white is a *light* paint, whatever I intend. Two lessons in one afternoon — (1) a pile's value is set mostly by how much lead white and yellow ochre are in it, not by the umber and black I add; (2) a bank is not a shape to be modelled in bands, it is a dark mass with a few light accidents in it. Going back over it darker, and leaving the light to single marks: stones, stalks, the lit edge of a tussock.")

print(wait(2 * 24 * 60))
ridgeP2 = pile{ {"raw umber",2.6}, {"yellow ochre",0.9}, {"pale smalt",1.0}, {"bone black",1.6} }
work(ridgeM, {hand="body", tool="filbert 9", pile=ridgeP2, coverage=2, fill=true,
              clip=true, edge="soft", pressure={0.3, 0.45},
              load_at=function(x, y)
                local v = nzBank(x * 1.1, y * 2.2)
                return 0.26 + 0.34 * clamp(0.5 + 0.9 * v, 0, 1)
              end})
print("ridge, darker")

